select tci.seed_statement_framework($fw${"framework":{"code":"DE_HGB","kind":"national_gaap","short":{"en":"HGB","ru":"HGB","uz":"HGB"},"name":{"en":"German Commercial Code (HGB)","ru":"Торговый кодекс Германии (HGB)","uz":"Germaniya Savdo kodeksi (HGB)"},"legal_basis":"Handelsgesetzbuch: § 266 HGB (Gliederung der Bilanz) und § 275 Abs. 2 HGB (Gewinn- und Verlustrechnung nach dem Gesamtkostenverfahren), i. d. F. des BilRUG 2015; ergänzend §§ 268, 272, 277 HGB. Österreich: §§ 224, 231 Abs. 2 UGB (gleiche Gliederungslogik, abweichende Postennummern, z. B. Bilanzgewinn statt Gewinnvortrag/Jahresüberschuss); Liechtenstein: Personen- und Gesellschaftsrecht (PGR), Gliederung nach der EU-Bilanzrichtlinie.","countries":["DE","AT","LI"]},"templates":[{"code":"DE_HGB_BS","form_kind":"balance_sheet","fidelity":"prescribed_captions","local_language":"de","name":{"en":"Balance sheet (HGB §266)","ru":"Бухгалтерский баланс (§266 HGB)","uz":"Buxgalteriya balansi (HGB §266)","local":"Bilanz (§ 266 HGB)"},"lines":[{"code":"A","section":"assets_long_term","indent":0,"subtotal":true,"negative":false,"name":{"en":"Fixed assets","ru":"Внеоборотные активы","uz":"Uzoq muddatli aktivlar","local":"Anlagevermögen"},"map":null,"formula":{"plus":["A.I","A.II","A.III"],"minus":[]},"check":null,"note":"not cross-checked: IFRS non-current assets also include D (deferred tax assets) and E (excess of plan assets), which HGB shows outside A"},{"code":"A.I","section":"assets_long_term","indent":1,"subtotal":true,"negative":false,"name":{"en":"Intangible assets","ru":"Нематериальные активы","uz":"Nomoddiy aktivlar","local":"Immaterielle Vermögensgegenstände"},"map":null,"formula":{"plus":["A.I.1","A.I.2","A.I.3","A.I.4"],"minus":[]},"check":null,"note":null},{"code":"A.I.1","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Self-created industrial property rights and similar rights and assets","ru":"Самостоятельно созданные промышленные права и аналогичные права и ценности","uz":"O‘zi yaratgan sanoat mulki huquqlari va shunga o‘xshash huquqlar va qiymatlar","local":"Selbst geschaffene gewerbliche Schutzrechte und ähnliche Rechte und Werte"},"map":{"column":"intangible_assets","sign":1},"formula":null,"check":null,"note":"capitalised development costs (§248 Abs. 2 HGB option)"},{"code":"A.I.2","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Purchased concessions, industrial property rights and similar rights and assets, and licences in such rights and assets","ru":"Приобретённые за плату концессии, промышленные права и аналогичные права и ценности, а также лицензии на них","uz":"Haq evaziga olingan konsessiyalar, sanoat mulki huquqlari va shunga o‘xshash huquqlar hamda ularga litsenziyalar","local":"Entgeltlich erworbene Konzessionen, gewerbliche Schutzrechte und ähnliche Rechte und Werte sowie Lizenzen an solchen Rechten und Werten"},"map":{"column":"intangible_assets","sign":1},"formula":null,"check":null,"note":null},{"code":"A.I.3","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Goodwill","ru":"Деловая репутация (гудвил)","uz":"Gudvill","local":"Geschäfts- oder Firmenwert"},"map":{"column":"goodwill","sign":1},"formula":null,"check":null,"note":null},{"code":"A.I.4","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Payments on account (intangible assets)","ru":"Авансы, выданные на нематериальные активы","uz":"Nomoddiy aktivlar uchun berilgan bo‘naklar","local":"Geleistete Anzahlungen"},"map":{"column":"intangible_assets","sign":1},"formula":null,"check":null,"note":null},{"code":"A.II","section":"assets_long_term","indent":1,"subtotal":true,"negative":false,"name":{"en":"Tangible fixed assets","ru":"Основные средства","uz":"Asosiy vositalar","local":"Sachanlagen"},"map":null,"formula":{"plus":["A.II.1","A.II.2","A.II.3","A.II.4"],"minus":[]},"check":null,"note":null},{"code":"A.II.1","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Land, land rights and buildings, including buildings on third-party land","ru":"Земельные участки, права, приравненные к земельным, и здания, включая здания на чужих участках","uz":"Yer uchastkalari, yerga tenglashtirilgan huquqlar va binolar, shu jumladan begona yerdagi binolar","local":"Grundstücke, grundstücksgleiche Rechte und Bauten einschließlich der Bauten auf fremden Grundstücken"},"map":{"column":"property_plant_equipment","sign":1},"formula":null,"check":null,"note":"HGB has no investment property line; let property is included here"},{"code":"A.II.2","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Technical equipment and machinery","ru":"Технические установки и машины","uz":"Texnik qurilmalar va mashinalar","local":"Technische Anlagen und Maschinen"},"map":{"column":"property_plant_equipment","sign":1},"formula":null,"check":null,"note":null},{"code":"A.II.3","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Other equipment, operating and office equipment","ru":"Прочее оборудование, производственный и офисный инвентарь","uz":"Boshqa uskunalar, ishlab chiqarish va idora jihozlari","local":"Andere Anlagen, Betriebs- und Geschäftsausstattung"},"map":{"column":"property_plant_equipment","sign":1},"formula":null,"check":null,"note":null},{"code":"A.II.4","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Payments on account and assets under construction","ru":"Авансы выданные и незавершённое строительство","uz":"Berilgan bo‘naklar va qurilishi tugallanmagan obyektlar","local":"Geleistete Anzahlungen und Anlagen im Bau"},"map":{"column":"property_plant_equipment","sign":1},"formula":null,"check":null,"note":null},{"code":"A.III","section":"assets_long_term","indent":1,"subtotal":true,"negative":false,"name":{"en":"Financial assets","ru":"Финансовые вложения","uz":"Moliyaviy investitsiyalar","local":"Finanzanlagen"},"map":null,"formula":{"plus":["A.III.1","A.III.2","A.III.3","A.III.4","A.III.5","A.III.6"],"minus":[]},"check":null,"note":null},{"code":"A.III.1","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Shares in affiliated companies","ru":"Доли в связанных предприятиях","uz":"Bog‘liq korxonalardagi ulushlar","local":"Anteile an verbundenen Unternehmen"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"A.III.2","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Loans to affiliated companies","ru":"Займы, выданные связанным предприятиям","uz":"Bog‘liq korxonalarga berilgan qarzlar","local":"Ausleihungen an verbundene Unternehmen"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"A.III.3","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Participations","ru":"Участия в других предприятиях","uz":"Ishtirok ulushlari","local":"Beteiligungen"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"A.III.4","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Loans to companies in which participations are held","ru":"Займы предприятиям, в которых имеется участие","uz":"Ishtirok ulushi mavjud korxonalarga berilgan qarzlar","local":"Ausleihungen an Unternehmen, mit denen ein Beteiligungsverhältnis besteht"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"A.III.5","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Securities held as fixed assets","ru":"Ценные бумаги, учитываемые в составе внеоборотных активов","uz":"Uzoq muddatli aktivlar tarkibidagi qimmatli qog‘ozlar","local":"Wertpapiere des Anlagevermögens"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"A.III.6","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Other loans","ru":"Прочие выданные займы","uz":"Boshqa berilgan qarzlar","local":"Sonstige Ausleihungen"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"B","section":"assets_current","indent":0,"subtotal":true,"negative":false,"name":{"en":"Current assets","ru":"Оборотные активы","uz":"Joriy aktivlar","local":"Umlaufvermögen"},"map":null,"formula":{"plus":["B.I","B.II","B.III","B.IV"],"minus":[]},"check":null,"note":"not cross-checked: IFRS current assets also include C (prepaid expenses), which HGB shows outside B"},{"code":"B.I","section":"assets_current","indent":1,"subtotal":true,"negative":false,"name":{"en":"Inventories","ru":"Запасы","uz":"Tovar-moddiy zaxiralar","local":"Vorräte"},"map":null,"formula":{"plus":["B.I.1","B.I.2","B.I.3","B.I.4"],"minus":["B.I.a"]},"check":null,"note":null},{"code":"B.I.1","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Raw materials, consumables and supplies","ru":"Сырьё, вспомогательные и эксплуатационные материалы","uz":"Xom ashyo, yordamchi va ekspluatatsiya materiallari","local":"Roh-, Hilfs- und Betriebsstoffe"},"map":{"column":"inventories","sign":1},"formula":null,"check":null,"note":null},{"code":"B.I.2","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Work in progress (goods and services)","ru":"Незавершённое производство (продукция и услуги)","uz":"Tugallanmagan ishlab chiqarish (mahsulot va xizmatlar)","local":"Unfertige Erzeugnisse, unfertige Leistungen"},"map":{"column":"inventories","sign":1},"formula":null,"check":null,"note":null},{"code":"B.I.3","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Finished goods and merchandise","ru":"Готовая продукция и товары","uz":"Tayyor mahsulot va tovarlar","local":"Fertige Erzeugnisse und Waren"},"map":{"column":"inventories","sign":1},"formula":null,"check":null,"note":null},{"code":"B.I.4","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Payments on account (inventories)","ru":"Авансы, выданные поставщикам запасов","uz":"Zaxiralar uchun mol yetkazib beruvchilarga berilgan bo‘naklar","local":"Geleistete Anzahlungen"},"map":{"column":"other_receivables","sign":1},"formula":null,"check":null,"note":"advances paid to suppliers are not inventory under IFRS; mapped to other receivables (as UZ NAS 270)"},{"code":"B.I.a","section":"assets_current","indent":2,"subtotal":false,"negative":true,"name":{"en":"Payments received on account of orders (deducted openly from inventories)","ru":"Полученные авансы по заказам (открыто вычтенные из запасов)","uz":"Buyurtmalar bo‘yicha olingan bo‘naklar (zaxiralardan ochiq chegirilgan)","local":"Erhaltene Anzahlungen auf Bestellungen (offen abgesetzt)"},"map":{"column":"inventories","sign":-1},"formula":null,"check":null,"note":"§268 Abs. 5 S. 2 HGB option, not a §266 outline item; kept netted against inventories as presented so the Bilanzsumme reconciles (IFRS would show a contract liability). Leave empty when the company shows them under P.C.3"},{"code":"B.II","section":"assets_current","indent":1,"subtotal":true,"negative":false,"name":{"en":"Receivables and other assets","ru":"Дебиторская задолженность и прочие активы","uz":"Debitorlik qarzlari va boshqa aktivlar","local":"Forderungen und sonstige Vermögensgegenstände"},"map":null,"formula":{"plus":["B.II.1","B.II.2","B.II.3","B.II.4"],"minus":[]},"check":null,"note":null},{"code":"B.II.1","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Trade receivables","ru":"Дебиторская задолженность по поставкам и услугам","uz":"Xaridorlar va buyurtmachilarning qarzlari","local":"Forderungen aus Lieferungen und Leistungen"},"map":{"column":"trade_receivables","sign":1},"formula":null,"check":null,"note":null},{"code":"B.II.2","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Receivables from affiliated companies","ru":"Задолженность связанных предприятий","uz":"Bog‘liq korxonalarning qarzlari","local":"Forderungen gegen verbundene Unternehmen"},"map":{"column":"other_receivables","sign":1},"formula":null,"check":null,"note":"mixes trade balances, cash-pool and loan receivables within the group; not split on the face"},{"code":"B.II.3","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Receivables from companies in which participations are held","ru":"Задолженность предприятий, в которых имеется участие","uz":"Ishtirok ulushi mavjud korxonalarning qarzlari","local":"Forderungen gegen Unternehmen, mit denen ein Beteiligungsverhältnis besteht"},"map":{"column":"other_receivables","sign":1},"formula":null,"check":null,"note":null},{"code":"B.II.4","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Other assets","ru":"Прочие активы","uz":"Boshqa aktivlar","local":"Sonstige Vermögensgegenstände"},"map":{"column":"other_receivables","sign":1},"formula":null,"check":null,"note":"also holds called but unpaid capital contributions (§272 Abs. 1 S. 3 HGB) when the company does not show them as a separate line"},{"code":"B.III","section":"assets_current","indent":1,"subtotal":true,"negative":false,"name":{"en":"Securities","ru":"Ценные бумаги","uz":"Qimmatli qog‘ozlar","local":"Wertpapiere"},"map":null,"formula":{"plus":["B.III.1","B.III.2"],"minus":[]},"check":null,"note":null},{"code":"B.III.1","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Shares in affiliated companies","ru":"Доли в связанных предприятиях","uz":"Bog‘liq korxonalardagi ulushlar","local":"Anteile an verbundenen Unternehmen"},"map":{"column":"short_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"B.III.2","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Other securities","ru":"Прочие ценные бумаги","uz":"Boshqa qimmatli qog‘ozlar","local":"Sonstige Wertpapiere"},"map":{"column":"short_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"B.IV","section":"assets_current","indent":1,"subtotal":false,"negative":false,"name":{"en":"Cash on hand, central bank balances, bank balances and cheques","ru":"Касса, остатки в Бундесбанке, на счетах в кредитных организациях и чеки","uz":"Kassadagi naqd pul, Bundesbank va kredit tashkilotlaridagi hisobvaraqlar qoldig‘i hamda cheklar","local":"Kassenbestand, Bundesbankguthaben, Guthaben bei Kreditinstituten und Schecks"},"map":{"column":"cash_and_equivalents","sign":1},"formula":null,"check":null,"note":null},{"code":"C","section":"assets_current","indent":0,"subtotal":false,"negative":false,"name":{"en":"Prepaid expenses","ru":"Расходы будущих периодов","uz":"Kelgusi davr xarajatlari","local":"Rechnungsabgrenzungsposten"},"map":{"column":"other_current_assets","sign":1},"formula":null,"check":null,"note":"active deferral (aktiver RAP); may include a capitalised bond discount (Disagio, §250 Abs. 3 HGB)"},{"code":"D","section":"assets_long_term","indent":0,"subtotal":false,"negative":false,"name":{"en":"Deferred tax assets","ru":"Отложенные налоговые активы","uz":"Kechiktirilgan soliq aktivlari","local":"Aktive latente Steuern"},"map":{"column":"deferred_tax_assets","sign":1},"formula":null,"check":null,"note":null},{"code":"E","section":"assets_long_term","indent":0,"subtotal":false,"negative":false,"name":{"en":"Excess of plan assets over pension liabilities","ru":"Активная разница от зачёта активов плана с пенсионными обязательствами","uz":"Pensiya rejasi aktivlarining majburiyatlardan oshgan qismi","local":"Aktiver Unterschiedsbetrag aus der Vermögensverrechnung"},"map":{"column":"other_non_current_assets","sign":1},"formula":null,"check":null,"note":"§246 Abs. 2 S. 3 HGB: plan assets netted with pension obligations exceed them"},{"code":"SUM.A","section":"assets_current","indent":0,"subtotal":true,"negative":false,"name":{"en":"Total assets","ru":"Итого актив (валюта баланса)","uz":"Balans aktivi bo‘yicha jami","local":"Summe Aktiva (Bilanzsumme)"},"map":null,"formula":{"plus":["A","B","C","D","E"],"minus":[]},"check":"total_assets","note":"not an outline item of §266; the Bilanzsumme printed on every balance sheet"},{"code":"P.A","section":"equity","indent":0,"subtotal":true,"negative":false,"name":{"en":"Equity","ru":"Собственный капитал","uz":"Xususiy kapital","local":"Eigenkapital"},"map":null,"formula":{"plus":["P.A.I","P.A.II","P.A.III","P.A.IV","P.A.V","P.A.BG"],"minus":["P.A.I.a","P.A.I.b"]},"check":"total_equity","note":"where equity is fully consumed (§268 Abs. 3 HGB, \"nicht durch Eigenkapital gedeckter Fehlbetrag\"), enter the equity components as printed so this total is negative, and do NOT enter the deficit line shown on the assets side; both Bilanzsummen are then lower than printed by that amount"},{"code":"P.A.I","section":"equity","indent":1,"subtotal":false,"negative":false,"name":{"en":"Subscribed capital","ru":"Подписной (уставный) капитал","uz":"Ustav kapitali (obuna bo‘lingan kapital)","local":"Gezeichnetes Kapital"},"map":{"column":"share_capital","sign":1},"formula":null,"check":null,"note":null},{"code":"P.A.I.a","section":"equity","indent":2,"subtotal":false,"negative":true,"name":{"en":"Uncalled outstanding capital contributions (deducted openly)","ru":"Невостребованные неоплаченные вклады (открыто вычтенные)","uz":"Talab qilinmagan, kiritilmagan ulushlar (ochiq chegirilgan)","local":"Nicht eingeforderte ausstehende Einlagen"},"map":{"column":"share_capital","sign":-1},"formula":null,"check":null,"note":"§272 Abs. 1 S. 3 HGB, deducted from subscribed capital on the face; not a §266 outline item"},{"code":"P.A.I.b","section":"equity","indent":2,"subtotal":false,"negative":true,"name":{"en":"Nominal value of own shares (deducted ope