select tci.seed_statement_framework($fw${"framework":{"code":"UK_FRS102","kind":"national_gaap","short":{"en":"FRS 102","ru":"FRS 102","uz":"FRS 102"},"name":{"en":"UK and Irish GAAP (FRS 102, Companies Act formats)","ru":"ОПБУ Великобритании и Ирландии (FRS 102, форматы Закона о компаниях)","uz":"Buyuk Britaniya va Irlandiya GAAP (FRS 102, Kompaniyalar to‘g‘risidagi qonun shakllari)"},"legal_basis":"Companies Act 2006; The Large and Medium-sized Companies and Groups (Accounts and Reports) Regulations 2008 (SI 2008/410), Schedule 1, Part 1, Section B: balance sheet Format 1 and profit and loss account Format 1, as amended by SI 2015/980; FRS 102 The Financial Reporting Standard applicable in the UK and Republic of Ireland (FRC). Ireland: Companies Act 2014, Schedule 3 (same formats).","countries":["GB","IE"]},"templates":[{"code":"UK_FRS102_BS","form_kind":"balance_sheet","fidelity":"prescribed_captions","local_language":"en","name":{"en":"Balance sheet (Companies Act Schedule 1, Format 1)","ru":"Бухгалтерский баланс (Приложение 1, формат 1)","uz":"Buxgalteriya balansi (1-ilova, 1-format)","local":"Balance sheet (Schedule 1, Format 1)"},"lines":[{"code":"A","section":"assets_current","indent":0,"subtotal":false,"negative":false,"name":{"en":"Called up share capital not paid","ru":"Востребованный, но не оплаченный акционерный капитал","uz":"Chaqirilgan, ammo to‘lanmagan ustav kapitali","local":"Called up share capital not paid"},"map":{"column":"other_receivables","sign":1},"formula":null,"check":null,"note":"called, so a receivable from shareholders; kept as an asset so the formats reconcile. Alternative position: C.II.5 — a company uses one or the other"},{"code":"B","section":"assets_long_term","indent":0,"subtotal":true,"negative":false,"name":{"en":"Fixed assets","ru":"Внеоборотные активы","uz":"Uzoq muddatli aktivlar","local":"Fixed assets"},"map":null,"formula":{"plus":["B.I","B.II","B.IP","B.III"],"minus":[]},"check":"total_non_current_assets","note":null},{"code":"B.I","section":"assets_long_term","indent":1,"subtotal":true,"negative":false,"name":{"en":"Intangible assets","ru":"Нематериальные активы","uz":"Nomoddiy aktivlar","local":"Intangible assets"},"map":null,"formula":{"plus":["B.I.1","B.I.2","B.I.3","B.I.4"],"minus":[]},"check":null,"note":null},{"code":"B.I.1","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Development costs","ru":"Затраты на разработки","uz":"Ishlanmalarga xarajatlar","local":"Development costs"},"map":{"column":"intangible_assets","sign":1},"formula":null,"check":null,"note":null},{"code":"B.I.2","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Concessions, patents, licences, trade marks and similar rights and assets","ru":"Концессии, патенты, лицензии, товарные знаки и аналогичные права и активы","uz":"Konsessiyalar, patentlar, litsenziyalar, tovar belgilari va shunga o‘xshash huquqlar va aktivlar","local":"Concessions, patents, licences, trade marks and similar rights and assets"},"map":{"column":"intangible_assets","sign":1},"formula":null,"check":null,"note":null},{"code":"B.I.3","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Goodwill","ru":"Деловая репутация (гудвил)","uz":"Gudvill","local":"Goodwill"},"map":{"column":"goodwill","sign":1},"formula":null,"check":null,"note":null},{"code":"B.I.4","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Payments on account (intangible assets)","ru":"Авансы, выданные на нематериальные активы","uz":"Nomoddiy aktivlar uchun berilgan bo‘naklar","local":"Payments on account"},"map":{"column":"intangible_assets","sign":1},"formula":null,"check":null,"note":null},{"code":"B.II","section":"assets_long_term","indent":1,"subtotal":true,"negative":false,"name":{"en":"Tangible assets","ru":"Основные средства","uz":"Asosiy vositalar","local":"Tangible assets"},"map":null,"formula":{"plus":["B.II.1","B.II.2","B.II.3","B.II.4"],"minus":[]},"check":null,"note":null},{"code":"B.II.1","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Land and buildings","ru":"Земля и здания","uz":"Yer va binolar","local":"Land and buildings"},"map":{"column":"property_plant_equipment","sign":1},"formula":null,"check":null,"note":null},{"code":"B.II.2","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Plant and machinery","ru":"Машины и оборудование","uz":"Mashina va uskunalar","local":"Plant and machinery"},"map":{"column":"property_plant_equipment","sign":1},"formula":null,"check":null,"note":null},{"code":"B.II.3","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Fixtures, fittings, tools and equipment","ru":"Приспособления, принадлежности, инструменты и инвентарь","uz":"Moslamalar, jihozlar, asboblar va inventar","local":"Fixtures, fittings, tools and equipment"},"map":{"column":"property_plant_equipment","sign":1},"formula":null,"check":null,"note":null},{"code":"B.II.4","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Payments on account and assets in course of construction","ru":"Авансы выданные и объекты незавершённого строительства","uz":"Berilgan bo‘naklar va qurilishi tugallanmagan obyektlar","local":"Payments on account and assets in course of construction"},"map":{"column":"property_plant_equipment","sign":1},"formula":null,"check":null,"note":null},{"code":"B.IP","section":"assets_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Investment property","ru":"Инвестиционная недвижимость","uz":"Investitsiya ko‘chmas mulki","local":"Investment property"},"map":{"column":"investment_property","sign":1},"formula":null,"check":null,"note":"not a Schedule 1 format item; FRS 102 s16 companies commonly add it under fixed assets (Sch.1 para 3 allows additional items). Leave empty when it is inside B.II.1. Code assigned here"},{"code":"B.III","section":"assets_long_term","indent":1,"subtotal":true,"negative":false,"name":{"en":"Investments (fixed assets)","ru":"Финансовые вложения (внеоборотные)","uz":"Uzoq muddatli investitsiyalar","local":"Investments"},"map":null,"formula":{"plus":["B.III.1","B.III.2","B.III.3","B.III.4","B.III.5","B.III.6","B.III.7"],"minus":[]},"check":null,"note":null},{"code":"B.III.1","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Shares in group undertakings","ru":"Акции (доли) в предприятиях группы","uz":"Guruh korxonalaridagi aksiyalar (ulushlar)","local":"Shares in group undertakings"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"B.III.2","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Loans to group undertakings","ru":"Займы предприятиям группы","uz":"Guruh korxonalariga berilgan qarzlar","local":"Loans to group undertakings"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"B.III.3","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Participating interests","ru":"Доли участия","uz":"Ishtirok ulushlari","local":"Participating interests"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"B.III.4","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Loans to undertakings in which the company has a participating interest","ru":"Займы предприятиям, в которых компания имеет долю участия","uz":"Kompaniya ishtirok ulushiga ega korxonalarga berilgan qarzlar","local":"Loans to undertakings in which the company has a participating interest"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"B.III.5","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Other investments other than loans","ru":"Прочие финансовые вложения, кроме займов","uz":"Qarzlardan tashqari boshqa investitsiyalar","local":"Other investments other than loans"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"B.III.6","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Other loans","ru":"Прочие выданные займы","uz":"Boshqa berilgan qarzlar","local":"Other loans"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"B.III.7","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Own shares","ru":"Собственные акции","uz":"Xususiy aksiyalar","local":"Own shares"},"map":{"column":"long_term_investments","sign":1},"formula":null,"check":null,"note":"code to be verified: kept from the original Format 1 list; under FRS 102 22.16 own shares are deducted from equity, so normally nil. Any legacy amount stays an asset so the totals reconcile"},{"code":"C","section":"assets_current","indent":0,"subtotal":true,"negative":false,"name":{"en":"Current assets","ru":"Оборотные активы","uz":"Joriy aktivlar","local":"Current assets"},"map":null,"formula":{"plus":["C.I","C.II","C.III","C.IV"],"minus":[]},"check":null,"note":"not cross-checked: prepayments may sit at D instead of C.II.6, and IFRS current assets include them either way"},{"code":"C.I","section":"assets_current","indent":1,"subtotal":true,"negative":false,"name":{"en":"Stocks","ru":"Запасы","uz":"Tovar-moddiy zaxiralar","local":"Stocks"},"map":null,"formula":{"plus":["C.I.1","C.I.2","C.I.3","C.I.4"],"minus":[]},"check":null,"note":null},{"code":"C.I.1","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Raw materials and consumables","ru":"Сырьё и материалы","uz":"Xom ashyo va materiallar","local":"Raw materials and consumables"},"map":{"column":"inventories","sign":1},"formula":null,"check":null,"note":null},{"code":"C.I.2","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Work in progress","ru":"Незавершённое производство","uz":"Tugallanmagan ishlab chiqarish","local":"Work in progress"},"map":{"column":"inventories","sign":1},"formula":null,"check":null,"note":null},{"code":"C.I.3","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Finished goods and goods for resale","ru":"Готовая продукция и товары для перепродажи","uz":"Tayyor mahsulot va qayta sotish uchun tovarlar","local":"Finished goods and goods for resale"},"map":{"column":"inventories","sign":1},"formula":null,"check":null,"note":null},{"code":"C.I.4","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Payments on account (stocks)","ru":"Авансы, выданные поставщикам запасов","uz":"Zaxiralar uchun berilgan bo‘naklar","local":"Payments on account"},"map":{"column":"other_receivables","sign":1},"formula":null,"check":null,"note":"advances paid to suppliers are not inventory under IFRS"},{"code":"C.II","section":"assets_current","indent":1,"subtotal":true,"negative":false,"name":{"en":"Debtors","ru":"Дебиторская задолженность","uz":"Debitorlik qarzlari","local":"Debtors"},"map":null,"formula":{"plus":["C.II.1","C.II.2","C.II.3","C.II.4","C.II.5","C.II.6"],"minus":[]},"check":null,"note":null},{"code":"C.II.1","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Trade debtors","ru":"Задолженность покупателей и заказчиков","uz":"Xaridorlar va buyurtmachilarning qarzlari","local":"Trade debtors"},"map":{"column":"trade_receivables","sign":1},"formula":null,"check":null,"note":null},{"code":"C.II.2","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Amounts owed by group undertakings","ru":"Задолженность предприятий группы","uz":"Guruh korxonalarining qarzlari","local":"Amounts owed by group undertakings"},"map":{"column":"other_receivables","sign":1},"formula":null,"check":null,"note":null},{"code":"C.II.3","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Amounts owed by undertakings in which the company has a participating interest","ru":"Задолженность предприятий, в которых компания имеет долю участия","uz":"Kompaniya ishtirok ulushiga ega korxonalarning qarzlari","local":"Amounts owed by undertakings in which the company has a participating interest"},"map":{"column":"other_receivables","sign":1},"formula":null,"check":null,"note":null},{"code":"C.II.4","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Other debtors","ru":"Прочие дебиторы","uz":"Boshqa debitorlar","local":"Other debtors"},"map":{"column":"other_receivables","sign":1},"formula":null,"check":null,"note":"FRS 102 deferred tax assets are usually presented within debtors; not separated here"},{"code":"C.II.5","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Called up share capital not paid","ru":"Востребованный, но не оплаченный акционерный капитал","uz":"Chaqirilgan, ammo to‘lanmagan ustav kapitali","local":"Called up share capital not paid"},"map":{"column":"other_receivables","sign":1},"formula":null,"check":null,"note":"alternative position of item A"},{"code":"C.II.6","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Prepayments and accrued income","ru":"Расходы будущих периодов и начисленные доходы","uz":"Kelgusi davr xarajatlari va hisoblangan daromadlar","local":"Prepayments and accrued income"},"map":{"column":"other_current_assets","sign":1},"formula":null,"check":null,"note":"alternative position of item D"},{"code":"C.II.LT","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Debtors: amounts falling due after more than one year (included above)","ru":"Дебиторская задолженность со сроком погашения свыше одного года (включена выше)","uz":"Bir yildan ortiq muddatda undiriladigan debitorlik qarzlari (yuqorida kiritilgan)","local":"Amounts falling due after more than one year"},"map":null,"formula":null,"check":null,"note":"memo: Schedule 1 requires it to be shown for each debtors item; already inside C.II, not mapped. Code assigned here"},{"code":"C.III","section":"assets_current","indent":1,"subtotal":true,"negative":false,"name":{"en":"Investments (current assets)","ru":"Краткосрочные финансовые вложения","uz":"Qisqa muddatli investitsiyalar","local":"Investments"},"map":null,"formula":{"plus":["C.III.1","C.III.2","C.III.3"],"minus":[]},"check":null,"note":null},{"code":"C.III.1","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Shares in group undertakings","ru":"Акции (доли) в предприятиях группы","uz":"Guruh korxonalaridagi aksiyalar (ulushlar)","local":"Shares in group undertakings"},"map":{"column":"short_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"C.III.2","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Own shares","ru":"Собственные акции","uz":"Xususiy aksiyalar","local":"Own shares"},"map":{"column":"short_term_investments","sign":1},"formula":null,"check":null,"note":"code to be verified: kept from the original Format 1 list; under FRS 102 22.16 own shares are deducted from equity, so normally nil"},{"code":"C.III.3","section":"assets_current","indent":2,"subtotal":false,"negative":false,"name":{"en":"Other investments","ru":"Прочие финансовые вложения","uz":"Boshqa investitsiyalar","local":"Other investments"},"map":{"column":"short_term_investments","sign":1},"formula":null,"check":null,"note":null},{"code":"C.IV","section":"assets_current","indent":1,"subtotal":false,"negative":false,"name":{"en":"Cash at bank and in hand","ru":"Денежные средства в банке и в кассе","uz":"Bankdagi va kassadagi pul mablag‘lari","local":"Cash at bank and in hand"},"map":{"column":"cash_and_equivalents","sign":1},"formula":null,"check":null,"note":null},{"code":"D","section":"assets_current","indent":0,"subtotal":false,"negative":false,"name":{"en":"Prepayments and accrued income","ru":"Расходы будущих периодов и начисленные доходы","uz":"Kelgusi davr xarajatlari va hisoblangan daromadlar","local":"Prepayments and accrued income"},"map":{"column":"other_current_assets","sign":1},"formula":null,"check":null,"note":"alternative position of C.II.6"},{"code":"E","section":"liabilities_current","indent":0,"subtotal":true,"negative":false,"name":{"en":"Creditors: amounts falling due within one year","ru":"Кредиторы: суммы со сроком погашения до одного года","uz":"Kreditorlar: bir yilgacha muddatda to‘lanadigan summalar","local":"Creditors: amounts falling due within one year"},"map":null,"formula":{"plus":["E.1","E.2","E.3","E.4","E.5","E.6","E.7","E.8","E.9"],"minus":[]},"check":null,"note":"not cross-checked: accruals may sit at J instead of E.9, and IFRS current liabilities include them either way"},{"code":"E.1","section":"liabilities_current","indent":1,"subtotal":false,"negative":false,"name":{"en":"Debenture loans (within one year)","ru":"Облигационные (долговые) займы (до одного года)","uz":"Obligatsiya qarzlari (bir yilgacha)","local":"Debenture loans"},"map":{"column":"short_term_borrowings","sign":1},"formula":null,"check":null,"note":null},{"code":"E.2","section":"liabilities_current","indent":1,"subtotal":false,"negative":false,"name":{"en":"Bank loans and overdrafts (within one year)","ru":"Банковские кредиты и овердрафты (до одного года)","uz":"Bank kreditlari va overdraftlar (bir yilgacha)","local":"Bank loans and overdrafts"},"map":{"column":"short_term_borrowings","sign":1},"formula":null,"check":null,"note":null},{"code":"E.3","section":"liabilities_current","indent":1,"subtotal":false,"negative":false,"name":{"en":"Payments received on account (within one year)","ru":"Полученные авансы (до одного года)","uz":"Olingan bo‘naklar (bir yilgacha)","local":"Payments received on account"