ction":"liabilities_current","indent":1,"subtotal":false,"negative":false,"name":{"en":"Other creditors including taxation and social security (within one year)","ru":"Прочие кредиторы, включая налоги и социальное обеспечение (до одного года)","uz":"Boshqa kreditorlar, shu jumladan soliqlar va ijtimoiy ta‘minot (bir yilgacha)","local":"Other creditors including taxation and social security"},"map":{"column":"other_payables","sign":1},"formula":null,"check":null,"note":"includes corporation tax payable, VAT and PAYE; the notes usually give corporation tax separately — not split here"},{"code":"E.9","section":"liabilities_current","indent":1,"subtotal":false,"negative":false,"name":{"en":"Accruals and deferred income (within one year)","ru":"Начисленные расходы и доходы будущих периодов (до одного года)","uz":"Hisoblangan xarajatlar va kelgusi davr daromadlari (bir yilgacha)","local":"Accruals and deferred income"},"map":{"column":"other_current_liabilities","sign":1},"formula":null,"check":null,"note":null},{"code":"F","section":"liabilities_current","indent":0,"subtotal":true,"negative":false,"name":{"en":"Net current assets (liabilities)","ru":"Чистые оборотные активы (обязательства)","uz":"Sof joriy aktivlar (majburiyatlar)","local":"Net current assets (liabilities)"},"map":null,"formula":{"plus":["C","D"],"minus":["E"]},"check":null,"note":"Format 1 note: prepayments are taken into account wherever shown; called up share capital not paid at A is not"},{"code":"G","section":"liabilities_long_term","indent":0,"subtotal":true,"negative":false,"name":{"en":"Total assets less current liabilities","ru":"Итого активы за вычетом краткосрочных обязательств","uz":"Jami aktivlar, joriy majburiyatlar chegirilgan holda","local":"Total assets less current liabilities"},"map":null,"formula":{"plus":["A","B","F"],"minus":[]},"check":null,"note":null},{"code":"H","section":"liabilities_long_term","indent":0,"subtotal":true,"negative":false,"name":{"en":"Creditors: amounts falling due after more than one year","ru":"Кредиторы: суммы со сроком погашения свыше одного года","uz":"Kreditorlar: bir yildan ortiq muddatda to‘lanadigan summalar","local":"Creditors: amounts falling due after more than one year"},"map":null,"formula":{"plus":["H.1","H.2","H.3","H.4","H.5","H.6","H.7","H.8","H.9"],"minus":[]},"check":null,"note":null},{"code":"H.1","section":"liabilities_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Debenture loans (after more than one year)","ru":"Облигационные (долговые) займы (свыше одного года)","uz":"Obligatsiya qarzlari (bir yildan ortiq)","local":"Debenture loans"},"map":{"column":"long_term_borrowings","sign":1},"formula":null,"check":null,"note":null},{"code":"H.2","section":"liabilities_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Bank loans and overdrafts (after more than one year)","ru":"Банковские кредиты и овердрафты (свыше одного года)","uz":"Bank kreditlari va overdraftlar (bir yildan ortiq)","local":"Bank loans and overdrafts"},"map":{"column":"long_term_borrowings","sign":1},"formula":null,"check":null,"note":null},{"code":"H.3","section":"liabilities_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Payments received on account (after more than one year)","ru":"Полученные авансы (свыше одного года)","uz":"Olingan bo‘naklar (bir yildan ortiq)","local":"Payments received on account"},"map":{"column":"other_non_current_liabilities","sign":1},"formula":null,"check":null,"note":null},{"code":"H.4","section":"liabilities_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Trade creditors (after more than one year)","ru":"Кредиторская задолженность поставщикам (свыше одного года)","uz":"Mol yetkazib beruvchilarga kreditorlik qarzlari (bir yildan ortiq)","local":"Trade creditors"},"map":{"column":"other_non_current_liabilities","sign":1},"formula":null,"check":null,"note":null},{"code":"H.5","section":"liabilities_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Bills of exchange payable (after more than one year)","ru":"Векселя к оплате (свыше одного года)","uz":"To‘lanadigan veksellar (bir yildan ortiq)","local":"Bills of exchange payable"},"map":{"column":"other_non_current_liabilities","sign":1},"formula":null,"check":null,"note":null},{"code":"H.6","section":"liabilities_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Amounts owed to group undertakings (after more than one year)","ru":"Задолженность перед предприятиями группы (свыше одного года)","uz":"Guruh korxonalari oldidagi qarzlar (bir yildan ortiq)","local":"Amounts owed to group undertakings"},"map":{"column":"other_non_current_liabilities","sign":1},"formula":null,"check":null,"note":"often long-term intra-group loans; reclassify to borrowings by hand when the notes show financing"},{"code":"H.7","section":"liabilities_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Amounts owed to undertakings in which the company has a participating interest (after more than one year)","ru":"Задолженность перед предприятиями, в которых компания имеет долю участия (свыше одного года)","uz":"Kompaniya ishtirok ulushiga ega korxonalar oldidagi qarzlar (bir yildan ortiq)","local":"Amounts owed to undertakings in which the company has a participating interest"},"map":{"column":"other_non_current_liabilities","sign":1},"formula":null,"check":null,"note":null},{"code":"H.8","section":"liabilities_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Other creditors including taxation and social security (after more than one year)","ru":"Прочие кредиторы, включая налоги и социальное обеспечение (свыше одного года)","uz":"Boshqa kreditorlar, shu jumladan soliqlar va ijtimoiy ta‘minot (bir yildan ortiq)","local":"Other creditors including taxation and social security"},"map":{"column":"other_non_current_liabilities","sign":1},"formula":null,"check":null,"note":null},{"code":"H.9","section":"liabilities_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Accruals and deferred income (after more than one year)","ru":"Начисленные расходы и доходы будущих периодов (свыше одного года)","uz":"Hisoblangan xarajatlar va kelgusi davr daromadlari (bir yildan ortiq)","local":"Accruals and deferred income"},"map":{"column":"other_non_current_liabilities","sign":1},"formula":null,"check":null,"note":"typically deferred government grants (FRS 102 s24) released after more than a year"},{"code":"I","section":"liabilities_long_term","indent":0,"subtotal":true,"negative":false,"name":{"en":"Provisions for liabilities","ru":"Резервы под обязательства","uz":"Majburiyatlar bo‘yicha rezervlar","local":"Provisions for liabilities"},"map":null,"formula":{"plus":["I.1","I.2","I.3"],"minus":[]},"check":null,"note":null},{"code":"I.1","section":"liabilities_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Pensions and similar obligations","ru":"Пенсионные и аналогичные обязательства","uz":"Pensiya va shunga o‘xshash majburiyatlar","local":"Pensions and similar obligations"},"map":{"column":"long_term_provisions","sign":1},"formula":null,"check":null,"note":null},{"code":"I.2","section":"liabilities_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Taxation, including deferred taxation","ru":"Налоги, включая отложенные налоги","uz":"Soliqlar, shu jumladan kechiktirilgan soliqlar","local":"Taxation, including deferred taxation"},"map":{"column":"deferred_tax_liabilities","sign":1},"formula":null,"check":null,"note":"in practice the deferred tax provision; current corporation tax payable sits in E.8"},{"code":"I.3","section":"liabilities_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"Other provisions","ru":"Прочие резервы","uz":"Boshqa rezervlar","local":"Other provisions"},"map":{"column":"long_term_provisions","sign":1},"formula":null,"check":null,"note":"Format 1 places provisions below total assets less current liabilities, so they are mapped non-current"},{"code":"J","section":"liabilities_current","indent":0,"subtotal":false,"negative":false,"name":{"en":"Accruals and deferred income","ru":"Начисленные расходы и доходы будущих периодов","uz":"Hisoblangan xarajatlar va kelgusi davr daromadlari","local":"Accruals and deferred income"},"map":{"column":"other_current_liabilities","sign":1},"formula":null,"check":null,"note":"alternative position of E.9/H.9; mapped current because accruals are overwhelmingly short-term"},{"code":"NA","section":"equity","indent":0,"subtotal":true,"negative":false,"name":{"en":"Net assets","ru":"Чистые активы","uz":"Sof aktivlar","local":"Net assets"},"map":null,"formula":{"plus":["G"],"minus":["H","I","J"]},"check":null,"note":"not a lettered format item: the customary total struck before capital and reserves; equals K when the sheet balances"},{"code":"K","section":"equity","indent":0,"subtotal":true,"negative":false,"name":{"en":"Capital and reserves","ru":"Капитал и резервы","uz":"Kapital va zaxiralar","local":"Capital and reserves"},"map":null,"formula":{"plus":["K.I","K.II","K.III","K.IV","K.V"],"minus":[]},"check":"total_equity","note":null},{"code":"K.I","section":"equity","indent":1,"subtotal":false,"negative":false,"name":{"en":"Called up share capital","ru":"Востребованный акционерный капитал","uz":"Chaqirilgan ustav kapitali","local":"Called up share capital"},"map":{"column":"share_capital","sign":1},"formula":null,"check":null,"note":null},{"code":"K.II","section":"equity","indent":1,"subtotal":false,"negative":false,"name":{"en":"Share premium account","ru":"Эмиссионный доход","uz":"Emissiya daromadi (aksiya mukofoti)","local":"Share premium account"},"map":{"column":"other_reserves","sign":1},"formula":null,"check":null,"note":null},{"code":"K.III","section":"equity","indent":1,"subtotal":false,"negative":false,"name":{"en":"Revaluation reserve","ru":"Резерв переоценки","uz":"Qayta baholash zaxirasi","lo