gan foyda (qoplanmagan zarar)","local":"Profit and loss account"},"map":{"column":"retained_earnings","sign":1},"formula":null,"check":null,"note":"signed: type an accumulated deficit as a negative number"}]},{"code":"UK_FRS102_PL","form_kind":"income_statement","fidelity":"prescribed_captions","local_language":"en","name":{"en":"Profit and loss account (Companies Act Schedule 1, Format 1)","ru":"Отчёт о прибылях и убытках (Приложение 1, формат 1)","uz":"Foyda va zararlar to‘g‘risidagi hisobot (1-ilova, 1-format)","local":"Profit and loss account (Schedule 1, Format 1)"},"lines":[{"code":"1","section":"operating","indent":0,"subtotal":false,"negative":false,"name":{"en":"Turnover","ru":"Выручка","uz":"Sotishdan tushgan tushum","local":"Turnover"},"map":{"column":"revenue","sign":1},"formula":null,"check":null,"note":null},{"code":"2","section":"operating","indent":0,"subtotal":false,"negative":true,"name":{"en":"Cost of sales","ru":"Себестоимость продаж","uz":"Sotilgan mahsulot tannarxi","local":"Cost of sales"},"map":{"column":"cost_of_sales","sign":1},"formula":null,"check":null,"note":null},{"code":"3","section":"operating","indent":0,"subtotal":true,"negative":false,"name":{"en":"Gross profit or loss","ru":"Валовая прибыль (убыток)","uz":"Yalpi foyda (zarar)","local":"Gross profit or loss"},"map":null,"formula":{"plus":["1"],"minus":["2"]},"check":"gross_profit","note":null},{"code":"4","section":"operating","indent":0,"subtotal":false,"negative":true,"name":{"en":"Distribution costs","ru":"Коммерческие расходы","uz":"Sotish xarajatlari","local":"Distribution costs"},"map":{"column":"distribution_expenses","sign":1},"formula":null,"check":null,"note":null},{"code":"5","section":"operating","indent":0,"subtotal":false,"negative":true,"name":{"en":"Administrative expenses","ru":"Административные расходы","uz":"Ma‘muriy xarajatlar","local":"Administrative expenses"},"map":{"column":"administrative_expenses","sign":1},"formula":null,"check":null,"note":null},{"code":"6","section":"operating","indent":0,"subtotal":false,"negative":false,"name":{"en":"Other operating income","ru":"Прочие операционные доходы","uz":"Boshqa operatsion daromadlar","local":"Other operating income"},"map":{"column":"other_operating_income","sign":1},"formula":null,"check":null,"note":null},{"code":"OP","section":"operating","indent":0,"subtotal":true,"negative":false,"name":{"en":"Operating profit or loss","ru":"Операционная прибыль (убыток)","uz":"Operatsion foyda (zarar)","local":"Operating profit (loss)"},"map":null,"formula":{"plus":["3","6"],"minus":["4","5"]},"check":"operating_profit","note":"not a Format 1 item, but printed on nearly every UK P&L; code assigned here. If the company reports none, it is still derived from items 3–6"},{"code":"7","section":"financial","indent":0,"subtotal":false,"negative":false,"name":{"en":"Income from shares in group undertakings","ru":"Доходы от акций (долей) в предприятиях группы","uz":"Guruh korxonalaridagi aksiyalar (ulushlar)dan daromadlar","local":"Income from shares in group undertakings"},"map":{"column":"finance_income","sign":1},"formula":null,"check":null,"note":null},{"code":"8","section":"financial","indent":0,"subtotal":false,"negative":false,"name":{"en":"Income from participating interests","ru":"Доходы от долей участия","uz":"Ishtirok ulushlaridan daromadlar","local":"Income from participating interests"},"map":{"column":"finance_income","sign":1},"formula":null,"check":null,"note":null},{"code":"9","section":"financial","indent":0,"subtotal":false,"negative":false,"name":{"en":"Income from other fixed asset investments","ru":"Доходы от прочих долгосрочных финансовых вложений","uz":"Boshqa uzoq muddatli investitsiyalardan daromadlar","local":"Income from other fixed asset investments"},"map":{"column":"finance_income","sign":1},"formula":null,"check":null,"note":null},{"code":"10","section":"financial","indent":0,"subtotal":false,"negative":false,"name":{"en":"Other interest receivable and similar income","ru":"Прочие проценты к получению и аналогичные доходы","uz":"Olinadigan boshqa foizlar va shunga o‘xshash daromadlar","local":"Other interest receivable and similar income"},"map":{"column":"finance_income","sign":1},"formula":null,"check":null,"note":null},{"code":"11","section":"financial","indent":0,"subtotal":false,"negative":true,"name":{"en":"Amounts written off investments","ru":"Списания финансовых вложений","uz":"Investitsiyalarni hisobdan chiqarish","local":"Amounts written off investments"},"map":{"column":"finance_costs","sign":1},"formula":null,"check":null,"note":null},{"code":"12","section":"financial","indent":0,"subtotal":false,"negative":true,"name":{"en":"Interest payable and similar expenses","ru":"Проценты к уплате и аналогичные расходы","uz":"To‘lanadigan foizlar va shunga o‘xshash xarajatlar","local":"Interest payable and similar expenses"},"map":{"column":"finance_costs","sign":1},"formula":null,"check":null,"note":null},{"code":"PBT","section":"result","indent":0,"subtotal":true,"negative":false,"name":{"en":"Profit or loss before taxation","ru":"Прибыль (убыток) до налогообложения","uz":"Soliq solinguniga qadar foyda (zarar)","local":"Profit or loss before taxation"},"map":null,"formula":{"plus":["OP","7","8","9","10"],"minus":["11","12"]},"check":"profit_before_tax","note":"required by Schedule 1 para 6 although not a numbered format item; code assigned here"},{"code":"13","section":"result","indent":0,"subtotal":false,"negative":true,"name":{"en":"Tax on profit or loss","ru":"Налог на прибыль","uz":"Foyda solig‘i","local":"Tax on profit or loss"},"map":{"column":"income_tax","sign":1},"formula":null,"check":null,"note":null},{"code":"14","section":"result","indent":0,"subtotal":true,"negative":false,"name":{"en":"Profit or loss after taxation","ru":"Прибыль (убыток) после налогообложения","uz":"Soliqdan keyingi foyda (zarar)","local":"Profit or loss after taxation"},"map":null,"formula":{"plus":["PBT"],"minus":["13"]},"check":null,"note":null},{"code":"19","section":"result","indent":0,"subtotal":false,"negative":true,"name":{"en":"Other taxes not shown under the above items","ru":"Прочие налоги, не отражённые в статьях выше","uz":"Yuqoridagi moddalarda ko‘rsatilmagan boshqa soliqlar","local":"Other taxes not shown under the above items"},"map":{"column":"income_tax","sign":1},"formula":null,"check":null,"note":"code to be verified (items 15–18, extraordinary items, were deleted by SI 2015/980 and the remaining items kept their numbers). Shown after profit before tax, so mapped to income tax to keep PBT and the result reconciling; almost always nil"},{"code":"20","section":"result","indent":0,"subtotal":true,"negative":false,"name":{"en":"Profit or loss for the financial year","ru":"Прибыль (убыток) за финансовый год","uz":"Moliya yilining foydasi (zarari)","local":"Profit or loss for the financial year"},"map":null,"formula":{"plus":["14"],"minus":["19"]},"check":"net_profit","note":"code to be verified (see item 19)"}]}]}$fw$::jsonb);

