select tci.seed_statement_framework($fw${"framework":{"code":"EU_DIRECTIVE","kind":"national_gaap","short":{"en":"EU Directive","ru":"Директива ЕС","uz":"YI direktiva"},"name":{"en":"EU Accounting Directive 2013/34/EU (national GAAP layouts)","ru":"Директива ЕС 2013/34/ЕС о бухгалтерской отчётности (национальные ОПБУ)","uz":"YI 2013/34/EU buxgalteriya hisobi direktivasi (milliy standartlar shakllari)"},"legal_basis":"Directive 2013/34/EU of the European Parliament and of the Council of 26 June 2013, Annex III (horizontal layout of the balance sheet, Article 10) and Annex V (profit and loss account by nature of expense, Article 13). National formats transpose these Annexes, e.g. Codice civile art. 2424 and 2425 (IT), Plan General de Contabilidad, Real Decreto 1514/2007 (ES), Sistema de Normalização Contabilística (PT), Burgerlijk Wetboek Boek 2 Titel 9 and Besluit modellen jaarrekening (NL), Ustawa o rachunkowości załącznik 1 (PL), Årsredovisningslagen (SE), Årsregnskapsloven (DK), Regnskapsloven (NO); EEA states via the EEA Agreement. Switzerland (Obligationenrecht art. 959a/959b) and Moldova (SNC aligned with the Directive) are mapped to this layout by analogy.","countries":["IT","ES","PT","NL","BE","LU","PL","CZ","SK","HU","RO","BG","HR","SI","EE","LV","LT","GR","CY","MT","DK","SE","FI","NO","IS","CH","MD"]},"templates":[{"code":"EU_DIRECTIVE_BS","form_kind":"balance_sheet","fidelity":"prescribed_captions","local_language":"en","name":{"en":"Balance sheet (Directive 2013/34/EU, Annex III)","ru":"Бухгалтерский баланс (Директива 2013/34/ЕС, Приложение III)","uz":"Buxgalteriya balansi (2013/34/EU direktivasi, III-ilova)","local":"Balance sheet — Annex III, horizontal layout (Directive 2013/34/EU)"},"lines":[{"code":"A","section":"assets_long_term","indent":0,"subtotal":false,"negative":false,"name":{"en":"Subscribed capital unpaid","ru":"Подписной капитал, не оплаченный","uz":"Obuna bo‘lingan, to‘lanmagan kapital","local":"Subscribed capital unpaid"},"map":{"column":"other_non_current_assets","sign":1},"formula":null,"check":null,"note":"enter the net (carrying) amounts of every asset line. IFRS would deduct uncalled capital from equity; kept as an asset as presented so the balance sheet totals reconcile. Some states show it in equity instead (then enter it nowhere here and use the national caption)"},{"code":"A.c","section":"assets_long_term","indent":1,"subtotal":false,"negative":false,"name":{"en":"of which there has been called","ru":"в том числе востребованный","uz":"shu jumladan talab qilingan","local":"of which there has been called"},"map":null,"formula":null,"check":null,"note":"memo of A; not mapped. Code assigned here"},{"code":"B","section":"assets_long_term","indent":0,"subtotal":false,"negative":false,"name":{"en":"Formation expenses","ru":"Расходы на создание предприятия (учредительские расходы)","uz":"Tashkil etish xarajatlari","local":"Formation expenses"},"map":{"column":"intangible_assets","sign":1},"formula":null,"check":null,"note":"only where national law allows them as an asset; IFRS would expense them. Kept as intangible so the totals reconcile"},{"code":"C","section":"assets_long_term","indent":0,"subtotal":true,"negative":false,"name":{"en":"Fixed assets","ru":"Внеоборотные активы","uz":"Uzoq muddatli aktivlar","local":"Fixed assets"},"map":null,"formula":{"plus":["C.I","C.II","C.III"],"minus":[]},"check":null,"note":"not cross-checked: IFRS non-current assets also take A (uncalled capital) and B (formation expenses), which the Annex shows outside C"},{"code":"C.I","section":"assets_long_term","indent":1,"subtotal":true,"negative":false,"name":{"en":"Intangible assets","ru":"Нематериальные активы","uz":"Nomoddiy aktivlar","local":"Intangible assets"},"map":null,"formula":{"plus":["C.I.1","C.I.2","C.I.3","C.I.4"],"minus":[]},"check":null,"note":null},{"code":"C.I.1","section":"assets_long_term","indent":2,"subtotal":false,"negative":false,"name":{"en":"Costs of development","ru":"Затраты на разработки",