,"name":{"en":"Legal reserve","ru":"Законный резерв","uz":"Qonun bo‘yicha zaxira","local":"Legal reserve"},"map":{"column":"other_reserves","sign":1},"formula":null,"check":null,"note":null},{"code":"P.A.IV.2","section":"equity","indent":2,"subtotal":false,"negative":false,"name":{"en":"Reserve for own shares","ru":"Резерв под собственные акции","uz":"Xususiy aksiyalar uchun zaxira","local":"Reserve for own shares"},"map":{"column":"other_reserves","sign":1},"formula":null,"check":null,"note":"where a national format deducts own shares here as a negative reserve, type it as a negative number"},{"code":"P.A.IV.3","section":"equity","indent":2,"subtotal":false,"negative":false,"name":{"en":"Reserves provided for by the articles of association","ru":"Резервы, предусмотренные уставом","uz":"Ustavda nazarda tutilgan zaxiralar","local":"Reserves provided for by the articles of association"},"map":{"column":"other_reserves","sign":1},"formula":null,"check":null,"note":null},{"code":"P.A.IV.4","section":"equity","indent":2,"subtotal":false,"negative":false,"name":{"en":"Other reserves, including the fair value reserve","ru":"Прочие резервы, включая резерв справедливой стоимости","uz":"Boshqa zaxiralar, shu jumladan adolatli qiymat zaxirasi","local":"Other reserves, including the fair value reserve"},"map":{"column":"other_reserves","sign":1},"formula":null,"check":null,"note":null},{"code":"P.A.V","section":"equity","indent":1,"subtotal":false,"negative":false,"name":{"en":"Profit or loss brought forward","ru":"Нераспределённая прибыль (непокрытый убыток) прошлых лет","uz":"O‘tgan yillarning taqsimlanmagan foydasi (qoplanmagan zarari)","local":"Profit or loss brought forward"},"map":{"column":"retained_earnings","sign":1},"formula":null,"check":null,"note":"signed: type a loss brought forward as a negative number"},{"code":"P.A.VI","section":"equity","indent":1,"subtotal":false,"negative":false,"name":{"en":"Profit or loss for the financial year","ru":"Прибыль (убыток) за ф