lse,"negative":false,"name":{"en":"Net turnover","ru":"Чистый оборот (выручка)","uz":"Sof tushum","local":"Net turnover"},"map":{"column":"revenue","sign":1},"formula":null,"check":null,"note":"nature-of-expense form: IFRS \"gross profit\" here means net turnover ± variation in stocks + own work capitalised − raw materials and consumables (items 1+2+3−5(a)); other external expenses, staff costs and value adjustments fall below it"},{"code":"2","section":"operating","indent":0,"subtotal":false,"negative":false,"name":{"en":"Variation in stocks of finished goods and in work in progress","ru":"Изменение остатков готовой продукции и незавершённого производства","uz":"Tayyor mahsulot va tugallanmagan ishlab chiqarish qoldiqlarining o‘zgarishi","local":"Variation in stocks of finished goods and in work in progress"},"map":{"column":"cost_of_sales","sign":-1},"formula":null,"check":null,"note":"signed: an increase is positive and reduces cost of sales; type a decrease as a negative number"},{"code":"3","section":"operating","indent":0,"subtotal":false,"negative":false,"name":{"en":"Work performed by the undertaking for its own purposes and capitalised","ru":"Работы, выполненные предприятием для собственных нужд и капитализированные","uz":"Korxona tomonidan o‘z ehtiyojlari uchun bajarilgan va kapitallashtirilgan ishlar","local":"Work performed by the undertaking for its own purposes and capitalised"},"map":{"column":"cost_of_sales","sign":-1},"formula":null,"check":null,"note":"own work capitalised offsets the costs it contains"},{"code":"4","section":"operating","indent":0,"subtotal":false,"negative":false,"name":{"en":"Other operating income","ru":"Прочие операционные доходы","uz":"Boshqa operatsion daromadlar","local":"Other operating income"},"map":{"column":"other_operating_income","sign":1},"formula":null,"check":null,"note":null},{"code":"5","section":"operating","indent":0,"subtotal":true,"negative":true,"name":{"en":"Raw materials and consumables and other external