s":["CA.a","CA.b.i","CA.b.ii","CA.b.iii","CA.b.iv","CA.b.v","CA.b.vi","CA.c","CA.d"],"minus":[]},"check":"total_current_assets","note":"printed by virtually every filer, though the Schedule III format itself lists only the items. Assets classified as held for sale (Ind AS 105), if presented, belong in Other current assets"},{"code":"TA","section":"assets_current","indent":0,"subtotal":true,"negative":false,"name":{"en":"Total Assets","ru":"Итого активы","uz":"Aktivlar, jami","local":"Total Assets"},"map":null,"formula":{"plus":["NCA","CA"],"minus":[]},"check":"total_assets","note":null},{"code":"EQ.a","section":"equity","indent":0,"subtotal":false,"negative":false,"name":{"en":"Equity Share capital","ru":"Акционерный капитал (обыкновенные акции)","uz":"Oddiy aksiyalar bo‘yicha aksiyadorlik kapitali","local":"Equity Share capital"},"map":{"column":"share_capital","sign":1},"formula":null,"check":null,"note":null},{"code":"EQ.b","section":"equity","indent":0,"subtotal":false,"negative":false,"name":{"en":"Other Equity","ru":"Прочий собственный капитал","uz":"Boshqa xususiy kapital","local":"Other Equity"},"map":{"column":"retained_earnings","sign":1},"formula":null,"check":null,"note":"one face line holding securities premium, general reserve, retained earnings and OCI reserves (split only in the Statement of Changes in Equity); mapped to retained earnings as the dominant component — move securities premium to share capital if the SOCE is available. Type a negative balance as a negative number"},{"code":"EQ.nci","section":"equity","indent":0,"subtotal":false,"negative":false,"name":{"en":"Non-controlling interests","ru":"Неконтролирующие доли","uz":"Nazorat qilmaydigan ulushlar","local":"Non-controlling interests"},"map":{"column":"non_controlling_interests","sign":1},"formula":null,"check":null,"note":"consolidated statements only; leave empty for standalone statements"},{"code":"EQ","section":"equity","indent":0,"subtotal":true,"negative":false,"name":{"en":"Total e