"section":"liabilities_long_term","indent":0,"subtotal":false,"negative":false,"name":{"en":"Other non-current liabilities","ru":"Прочие долгосрочные обязательства","uz":"Boshqa uzoq muddatli majburiyatlar","local":"Other non-current liabilities"},"map":{"column":"other_non_current_liabilities","sign":1},"formula":null,"check":null,"note":"deferred government grants, long-term advances"},{"code":"NCL","section":"liabilities_long_term","indent":0,"subtotal":true,"negative":false,"name":{"en":"Total non-current liabilities","ru":"Итого долгосрочные обязательства","uz":"Uzoq muddatli majburiyatlar, jami","local":"Total non-current liabilities"},"map":null,"formula":{"plus":["NCL.a.i","NCL.a.ia","NCL.a.ii","NCL.a.iii","NCL.b","NCL.c","NCL.d"],"minus":[]},"check":"total_non_current_liabilities","note":"printed by virtually every filer, though the Schedule III format itself lists only the items"},{"code":"CL.a.i","section":"liabilities_current","indent":1,"subtotal":false,"negative":false,"name":{"en":"Financial Liabilities: (i) Borrowings","ru":"Финансовые обязательства: кредиты и займы","uz":"Moliyaviy majburiyatlar: kreditlar va qarzlar","local":"(i) Borrowings"},"map":{"column":"short_term_borrowings","sign":1},"formula":null,"check":null,"note":"since the 2021 amendment includes current maturities of long-term borrowings"},{"code":"CL.a.ia","section":"liabilities_current","indent":1,"subtotal":false,"negative":false,"name":{"en":"Financial Liabilities: (ia) Lease liabilities","ru":"Финансовые обязательства: обязательства по аренде","uz":"Moliyaviy majburiyatlar: ijara majburiyatlari","local":"(ia) Lease liabilities"},"map":{"column":"short_term_borrowings","sign":1},"formula":null,"check":null,"note":"Ind AS 116 lease liabilities are interest-bearing and counted as borrowings"},{"code":"CL.a.ii","section":"liabilities_current","indent":1,"subtotal":true,"negative":false,"name":{"en":"Financial Liabilities: (ii) Trade payables","ru":"Финансовые обязательства: кредитор