p":{"column":"other_current_liabilities","sign":1},"formula":null,"check":null,"note":"advances from customers (contract liabilities), statutory dues"},{"code":"CL.c","section":"liabilities_current","indent":0,"subtotal":false,"negative":false,"name":{"en":"Provisions","ru":"Оценочные обязательства (резервы)","uz":"Zaxiralar (baholangan majburiyatlar)","local":"Provisions"},"map":{"column":"short_term_provisions","sign":1},"formula":null,"check":null,"note":null},{"code":"CL.d","section":"liabilities_current","indent":0,"subtotal":false,"negative":false,"name":{"en":"Current Tax Liabilities (Net)","ru":"Текущие налоговые обязательства (нетто)","uz":"Joriy soliq majburiyatlari (sof)","local":"Current Tax Liabilities (Net)"},"map":{"column":"current_tax_liabilities","sign":1},"formula":null,"check":null,"note":null},{"code":"CL","section":"liabilities_current","indent":0,"subtotal":true,"negative":false,"name":{"en":"Total current liabilities","ru":"Итого краткосрочные обязательства","uz":"Joriy majburiyatlar, jami","local":"Total current liabilities"},"map":null,"formula":{"plus":["CL.a.i","CL.a.ia","CL.a.ii","CL.a.iii","CL.b","CL.c","CL.d"],"minus":[]},"check":"total_current_liabilities","note":"printed by virtually every filer, though the Schedule III format itself lists only the items"},{"code":"TEL","section":"liabilities_current","indent":0,"subtotal":true,"negative":false,"name":{"en":"Total Equity and Liabilities","ru":"Итого собственный капитал и обязательства","uz":"Xususiy kapital va majburiyatlar, jami","local":"Total Equity and Liabilities"},"map":null,"formula":{"plus":["EQ","NCL","CL"],"minus":[]},"check":"total_equity_and_liabilities","note":null}]},{"code":"IN_SCHED3_PL","form_kind":"income_statement","fidelity":"prescribed_captions","local_language":"en","name":{"en":"Statement of profit and loss (Schedule III, Division II)","ru":"Отчёт о прибылях и убытках (Приложение III, Раздел II)","uz":"Foyda va zararlar to‘g‘risidagi hisobot (III-ilova, II bo‘lim)","local":"Statement of Profit and Loss"},"lines":[{"code":"I","section":"operating","indent":0,"subtotal":false,"negative":false,"name":{"en":"Revenue from operations","ru":"Выручка от операционной деятельности","uz":"Asosiy faoliyatdan tushum","local":"I. Revenue From Operations"},"map":{"column":"revenue","sign":1},"formula":null,"check":null,"note":null},{"code":"II","section":"financial","indent":0,"subtotal":false,"negative":false,"name":{"en":"Other income","ru":"Прочие доходы","uz":"Boshqa daromadlar","local":"II. Other Income"},"map":{"column":"finance_income","sign":1},"formula":null,"check":null,"note":"judgement call: for most Indian filers other income is predominantly interest, dividends, gains on investments and FX gains, so it is treated as finance income rather than inflating operating profit; Schedule III prints no operating-profit line, so no cross-check depends on this choice"},{"code":"III","section":"operating","indent":0,"subtotal":true,"negative":false,"name":{"en":"Total income (I+II)","ru":"Итого доходы (I+II)","uz":"Daromadlar, jami (I+II)","local":"III. Total Income (I+II)"},"map":null,"formula":{"plus":["I","II"],"minus":[]},"check":null,"note":null},{"code":"IV.a","section":"operating","indent":1,"subtotal":false,"negative":true,"name":{"en":"Cost of materials consumed","ru":"Стоимость израсходованных материалов","uz":"Sarflangan materiallar qiymati","local":"Cost of materials consumed"},"map":{"column":"cost_of_sales","sign":1},"formula":null,"check":null,"note":null},{"code":"IV.b","section":"operating","indent":1,"subtotal":false,"negative":true,"name":{"en":"Purchases of stock-in-trade","ru":"Закупки товаров для перепродажи","uz":"Qayta sotish uchun xarid qilingan tovarlar","local":"Purchases of Stock-in-Trade"},"map":{"column":"cost_of_sales","sign":1},"formula":null,"check":null,"note":null},{"code":"IV.c","section":"operating","indent":1,"subtotal":false,"negative":true,"name":{"en":"Changes in inventories of finished goods, stock-in-trade and work-in-progress","ru":"Изменение запасов готовой продукции, товаров и незавершённого производства","uz":"Tayyor mahsulot, tovarlar va tugallanmagan ishlab chiqarish zaxiralarining o‘zgarishi","local":"Changes in inventories of finished goods, Stock-in-Trade and work-in-progress"},"map":{"column":"cost_of_sales","sign":1},"formula":null,"check":null,"note":"signed as presented, (increase)/decrease: a DECREASE adds to expenses (positive), an INCREASE is typed as a negative number"},{"code":"IV.d","section":"operating","indent":1,"subtotal":false,"negative":true,"name":{"en":"Employee benefits expense","ru":"Расходы на вознаграждения работникам","uz":"Xodimlarga to‘lovlar bo‘yicha xarajatlar","local":"Employee benefits expense"},"map":{"column":"other_operating_expenses","sign":1},"formula":null,"check":null,"note":"by-nature expense with no functional split; operating, so other operating expenses"},{"code":"IV.e","section":"financial","indent":1,"subtotal":false,"negative":true,"name":{"en":"Finance costs","ru":"Финансовые расходы","uz":"Moliyaviy xarajatlar","local":"Finance costs"},"map":{"column":"finance_costs","sign":1},"formula":null,"check":null,"note":null},{"code":"IV.f","section":"operating","indent":1,"subtotal":false,"negative":true,"name":{"en":"Depreciation and amortisation expense","ru":"Амортизация","uz":"Amortizatsiya xarajatlari","local":"Depreciation and amortization expense"},"map":{"column":"other_operating_expenses","sign":1},"formula":null,"check":null,"note":"mapped to other operating expenses so it reduces operating profit; the memo column depreciation_amortization cannot be filled from the same line"},{"code":"IV.g","section":"operating","indent":1,"subtotal":false,"negative":true,"name":{"en":"Other expenses","ru":"Прочие расходы","uz":"Boshqa xarajatlar","local":"Other expenses"},"map":{"column":"other_operating_expenses","sign":1},"formula":null,"check":null,"note":"power, freight, rent, repairs, selling and administrative overheads (by nature)"},{"code":"IV","section":"operating","indent":0,"subtotal":true,"negative":true,"name":{"en":"Total expenses (IV)","ru":"Итого расходы (IV)","uz":"Xarajatlar, jami (IV)","local":"Total expenses (IV)"},"map":null,"formula":{"plus":["IV.a","IV.b","IV.c","IV.d","IV.e","IV.f","IV.g"],"minus":[]},"check":null,"note":null},{"code":"V","section":"result","indent":0,"subtotal":true,"negative":false,"name":{"en":"Profit/(loss) before exceptional items and tax (III-IV)","ru":"Прибыль (убыток) до исключительных статей и налогообложения (III-IV)","uz":"Favqulodda moddalar va soliqqa qadar foyda (zarar) (III-IV)","local":"V. Profit/(loss) before exceptional items and tax (III-IV)"},"map":null,"formula":{"plus":["III"],"minus":["IV"]},"check":null,"note":"no IFRS equivalent (after finance costs, before exceptional items); not cross-checked"},{"code":"VI","section":"result","indent":0,"subtotal":false,"negative":true,"name":{"en":"Exceptional items","ru":"Исключительные статьи","uz":"Favqulodda moddalar","local":"VI. Exceptional Items"},"map":{"column":"other_non_operating","sign":-1},"formula":null,"check":null,"note":"the form deducts it (VII = V − VI): an exceptional EXPENSE is typed positive, an exceptional GAIN as a negative number"},{"code":"VII","section":"result","indent":0,"subtotal":true,"negative":false,"name":{"en":"Profit/(loss) before tax (V-VI)","ru":"Прибыль (убыток) до налогообложения (V-VI)","uz":"Soliqqa qadar foyda (zarar) (V-VI)","local":"VII. Profit/(loss) before tax (V-VI)"},"map":null,"formula":{"plus":["V"],"minus":["VI"]},"check":"profit_before_tax","note":null},{"code":"VIII.1","section":"result","indent":1,"subtotal":false,"negative":true,"name":{"en":"Current tax","ru":"Текущий налог на прибыль","uz":"Joriy foyda solig‘i","local":"(1) Current tax"},"map":{"column":"income_tax","sign":1},"formula":null,"check":null,"note":null},{"code":"VIII.2","section":"result","indent":1,"subtotal":false,"negative":true,"name":{"en":"Deferred tax","ru":"Отложенный налог на прибыль","uz":"Kechiktirilgan foyda solig‘i","local":"(2) Deferred tax"},"map":{"column":"income_tax","sign":1},"formula":null,"check":null,"note":"a deferred tax credit is typed as a negative number"},{"code":"VIII","section":"result","indent":0,"subtotal":true,"negative":true,"name":{"en":"Tax expense","ru":"Расход по налогу на прибыль","uz":"Foyda solig‘i bo‘yicha xarajat","local":"VIII. Tax expense:"},"map":null,"formula":{"plus":["VIII.1","VIII.2"],"minus":[]},"check":null,"note":null},{"code":"IX","section":"result","indent":0,"subtotal":true,"negative":false,"name":{"en":"Profit/(loss) for the period from continuing operations (VII-VIII)","ru":"Прибыль (убыток) за период от продолжающейся деятельности (VII-VIII)","uz":"Davom etayotgan faoliyatdan davr foydasi (zarari) (VII-VIII)","local":"IX. Profit (Loss) for the period from continuing operations (VII-VIII)"},"map":null,"formula":{"plus":["VII"],"minus":["VIII"]},"check":"net_profit","note":"checked against IFRS net profit: discontinued operations (X–XII) have no IFRS column and are left out of the analysis"},{"code":"X","section":"result","indent":0,"subtotal":false,"negative":false,"name":{"en":"Profit/(loss) from discontinued operations","ru":"Прибыль (убыток) от прекращённой деятельности","uz":"To‘xtatilgan faoliyatdan foyda (zarar)","local":"X. Profit/(loss) from discontinued operations"},"map":null,"formula":null,"check":null,"note":"Ind AS 105; no IFRS column, not mapped"},{"code":"XI","section":"result","indent":0,"subtotal":false,"negative":true,"name":{"en":"Tax expense of discontinued operations","ru":"Расход по налогу на прибыль от прекращённой деятельности","uz":"To‘xtatilgan faoliyat bo‘yicha foyda solig‘i","local":"XI. Tax expense of discontinued operations"},"map":null,"formula":null,"check":null,"note":"Ind AS 105; no IFRS column, not mapped"},{"code":"XII","section":"result","indent":0,"subtotal":true,"negative":false,"name":{"en":"Profit/(loss) from disconti