do $$
declare v_n int; v_bad text;
begin
  select count(*) into v_n from tci.statement_templates
   where framework_code in ('RU_RAS', 'BY_NSBU', 'KZ_NSFO', 'UA_NPSBU', 'DE_HGB', 'FR_PCG', 'UK_FRS102', 'EU_DIRECTIVE', 'US_GAAP', 'CN_CAS', 'JP_GAAP', 'IN_SCHED3', 'TR_TDHP', 'BR_LEI6404', 'VN_VAS');
  if v_n <> 30 then
    raise exception '0051: expected 30 templates, found %', v_n;
  end if;
  select string_agg(t.code, ', ') into v_bad from tci.statement_templates t
   where t.framework_code in ('RU_RAS', 'BY_NSBU', 'KZ_NSFO', 'UA_NPSBU', 'DE_HGB', 'FR_PCG', 'UK_FRS102', 'EU_DIRECTIVE', 'US_GAAP', 'CN_CAS', 'JP_GAAP', 'IN_SCHED3', 'TR_TDHP', 'BR_LEI6404', 'VN_VAS')
     and not exists (select 1 from tci.statement_template_lines l
                      where l.template_id = t.id and l.crosscheck_column is not null);
  if v_bad is not null then
    raise exception '0051: template(s) without a cross-check: %', v_bad;
  end if;
  -- a formula never names a line its template does not have
  select string_agg(distinct t.code || ':' || l.line_code, ', ') into v_bad
    from tci.statement_template_lines l
    join tci.statement_templates t on t.id = l.template_id
    cross join lateral jsonb_array_elements_text(l.formula -> 'plus' || l.formula -> 'minus') as ref(code)
   where l.formula is not null
     and not exists (select 1 from tci.statement_template_lines x
                      where x.template_id = l.template_id and x.line_code = ref.code);
  if v_bad is not null then
    raise exception '0051: formula references to unknown lines: %', v_bad;
  end if;
end;
$$;
